using RvtIO.Internal;
using RvtIO.Parsing;
using Xunit;

namespace RvtIO.Tests;

public class PlanarSpaceEdgeLoopTests
{
    // Complete geometry-only cache, owner 7481072, 23 source Faces. Face 4 has
    // six authored loops, two touching at one vertex. The coordinate-only graph
    // loses five edges; the serialized loop partition retains all 28 regions.
    private const string Fixture = "";

    [Fact]
    public void AuthoredTouchingLoops_RetainAllRegionsWithoutChangingSource()
    {
        byte[] block = Convert.FromBase64String(Fixture);
        var geometry = Assert.IsType<GRepData>(Parse(block));
        Assert.Equal(28, geometry.Faces.Count);
        var solid = Assert.Single(geometry.Solids);
        Assert.True(solid.IsClosed);
        Assert.Equal(Enumerable.Range(0, 28), solid.FaceIndices.Order());
        var model = Assert.IsType<RvtIO.Model.GeometryData>(ElementBuilder.BuildGeometryData(geometry));
        Assert.True(RvtIO.Ifc.IfcExporter.TryOrientExactFacetedShell(model.Faces,
            solid.FaceIndices, out _, triangulateNonPlanarFaces: false));
        Assert.Null(GRepParserV2.Parse(block, 0, BitConverter.ToUInt32(block, 8)));
        Assert.Equal(Convert.FromBase64String(Fixture), block);
    }

    // Offsets are exact schema-walked fields, not signature matches.
    // Loop 102 starts at 10149; its non-null nextLoop pointer takes six bytes.
    [Theory]
    [InlineData("loop-owner")]
    [InlineData("loop-first-missing")]
    [InlineData("loop-last-missing")]
    [InlineData("loop-first-wrong")]
    [InlineData("loop-last-wrong")]
    [InlineData("loop-open")]
    [InlineData("loop-flags")]
    [InlineData("duplicate-loop-handle")]
    [InlineData("loop-edge-handle-collision")]
    [InlineData("loop-class")]
    [InlineData("edge-next-missing")]
    [InlineData("edge-prev-missing")]
    [InlineData("edge-self-cycle")]
    [InlineData("edge-premature-end")]
    [InlineData("edge-owner")]
    [InlineData("edge-coordinate-gap")]
    [InlineData("edge-nonfinite")]
    public void InvalidAuthoredLoopContracts_FailClosed(string mutation)
    {
        byte[] block = Convert.FromBase64String(Fixture);
        void U32(int offset, uint value) => BitConverter.GetBytes(value).CopyTo(block, offset);
        switch (mutation)
        {
            case "loop-owner": U32(10149 + 22, 5); break;
            case "loop-first-missing": U32(10149 + 26, 999999); break;
            case "loop-last-missing": U32(10149 + 30, 999999); break;
            case "loop-first-wrong": U32(10149 + 26, 28); break;
            case "loop-last-wrong": U32(10149 + 30, 28); break;
            case "loop-open": block[10149 + 66] = 1; break;
            case "loop-flags": U32(10149 + 12, 0); break;
            case "duplicate-loop-handle": U32(10149 + 16, 102); break;
            case "loop-edge-handle-collision": U32(10149 + 16, 27); break;
            case "loop-class": BitConverter.GetBytes((ushort)522).CopyTo(block, 10149 + 20); break;
            case "edge-next-missing": U32(1974 + 24, 999999); break;
            case "edge-prev-missing": U32(1974 + 32, 999999); break;
            case "edge-self-cycle": U32(1974 + 24, 27); break;
            case "edge-premature-end": U32(1974 + 24, 102); break;
            case "edge-owner": U32(1974 + 16, 5); break;
            case "edge-coordinate-gap":
                BitConverter.GetBytes(BitConverter.ToDouble(block, 1974 + 44) + .01).CopyTo(block, 1974 + 44); break;
            case "edge-nonfinite": BitConverter.GetBytes(double.NaN).CopyTo(block, 1974 + 44); break;
        }
        Assert.Null(Parse(block));
    }

    [Theory]
    [InlineData(10149)]
    [InlineData(10149 + 22)]
    [InlineData(10149 + 26)]
    [InlineData(10149 + 30)]
    [InlineData(10149 + 66)]
    [InlineData(10321)]
    [InlineData(14488)]
    public void TruncatedLoopTail_FailsClosedEvenWithRewrittenFooter(int length)
    {
        var block = Convert.FromBase64String(Fixture)[..length];
        Assert.Null(Parse(block));
        uint size = (uint)length - 16;
        BitConverter.GetBytes(size).CopyTo(block, 8);
        BitConverter.GetBytes(size).CopyTo(block, length - 4);
        Assert.Null(Parse(block));
    }

    private static GRepData? Parse(byte[] block) =>
        GRepParserV2.ParseExactPlanarSpaceBoundary(block, 0, BitConverter.ToUInt32(block, 8), 7481072);
}

